-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.arm_words(p_name text, p_px double precision, p_py double precision, p_x double precision, p_y double precision)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select p_name || ': ' || track_point(8, floor(track_bearing(p_px, p_py, p_x, p_y) / 45 + 0.5)::int % 8) || ', '
      || (floor(track_bearing(p_px, p_py, p_x, p_y) + 0.5)::int % 360) || '°, '
      || floor(sqrt((p_x - p_px) ^ 2 + (p_y - p_py) ^ 2) + 0.5)::int || ' tiles'
$function$
